import sys; sys.path.insert(0, __import__("os").path.join(__import__("os").path.dirname(__file__), "..", "..", "pipeline"))
from scriptkit import sc, ch, save, S

# Grandma Ruth 27 · everyday recipe: white chicken chili (Google Trends 3/11: white chicken chili +160%)
# Grandma Ruth: born 1944 in Mansfield, Ohio; mother Dorothy, father Walter, brother Danny, Grandma Pearl.

sc("""Sweetheart, I'm going to tell you something my mother would never have believed. The best chili I make isn't red. It's white. Chicken, white beans, green chiles, and a creamy broth that tastes like it cooked all day, and it's ready in forty-five minutes. My grandson asks for it every single time he comes home from college, before he even takes his coat off.""",
   "white chicken chili bowl", "THE BEST CHILI ISN'T RED")
sc("""But almost everybody who makes it at home tells me the same thing. Grandma, mine tastes like nothing. It's watery and bland, like chicken soup that forgot what it was. So tonight I'm giving you my white chicken chili, every ingredient, every step, and the five mistakes that make it bland. One pot, and it feeds six people for about twelve dollars.""",
   "watery soup bowl bland", "LIKE CHICKEN SOUP THAT FORGOT")

ch("A chili from my daughter-in-law")
sc("""Now, I didn't grow up with this. In Mansfield in the fifties, chili was red. Ground beef, kidney beans, a can of tomatoes, and a spoon of chili powder, served on Saturday night with saltine crackers. My father put a slice of cheese on top and called it Texas style. He had never been to Texas. None of us had.""",
   "1950s chili bowl saltine crackers", "HE HAD NEVER BEEN TO TEXAS")
sc("""The white chili came into my kitchen in nineteen ninety-three, from my daughter-in-law, Linda, who grew up in New Mexico. She made it for a church supper, and I went back for seconds, and then for thirds, and then I went into the kitchen and stood next to her until she told me everything. White chili was all the rage at church suppers in the nineties. It still should be.""",
   "church supper potluck table", "I WENT BACK FOR THIRDS")
sc("""And I changed a few things over thirty years, the way grandmothers do. Linda used chicken breasts, and I use thighs. She used water and I use broth. And I added the one thing that made her say, Ruth, that's better than mine. I'll tell you what it is. But first, the list.""",
   "grandmother cooking stove pot", "BETTER THAN MINE")

ch("What you need")
sc("""Here's what you need, honey. Two pounds of boneless chicken thighs. One big onion, chopped. Four cloves of garlic. Two cans of chopped green chiles, the four-ounce cans, mild or hot, your choice. Three cans of white beans, great northern or cannellini, drained and rinsed. And four cups of chicken broth.""",
   "chicken thighs onion green chiles cans", "THIGHS, NOT BREASTS")
sc("""For the seasoning. Two teaspoons of ground cumin. One teaspoon of dried oregano. One teaspoon of chili powder. Salt and pepper. And at the end, four ounces of cream cheese, half a cup of sour cream, the juice of one lime, and a handful of chopped cilantro, if you like it. My husband said cilantro tasted like soap, so half the pot never got any.""",
   "cumin oregano spices lime cream cheese", "CILANTRO TASTED LIKE SOAP")
sc("""Why thighs, sweetheart? Because chicken breast cooks dry and stringy in a pot of simmering broth. Thighs have a little fat, and they stay tender and juicy, and they give the broth flavor. They're cheaper, too. If you only have breasts, fine, but take them out as soon as they're cooked through and shred them, and don't let them boil.""",
   "boneless chicken thighs raw", "THEY STAY TENDER")

sc("""And rinse the canned beans, honey. That thick, cloudy liquid in the can is salty and starchy, and it makes the chili taste tinny. Pour them into a colander and run cold water over them until the water runs clear. If you'd rather cook dried beans, a pound of dried great northern beans, soaked overnight, is about the same as three cans, and it costs half as much.""",
   "rinsing canned beans colander", "RINSE THE BEANS")

ch("Step by step")
sc("""Step one. Salt and pepper the chicken thighs. Heat a spoon of oil in a big heavy pot until it shimmers, and lay the thighs in, flat. Let them brown for four minutes on each side without moving them. They don't need to cook through. You just want a golden crust. That brown crust is mistake number one, the flavor everybody skips.""",
   "browning chicken thighs pot", "A GOLDEN CRUST")
sc("""Step two. Take the chicken out and put it on a plate. Put the onion in the same pot, in all that chicken fat, and cook it for five or six minutes until it's soft and starting to turn gold. Then the garlic for one minute. Scrape up the brown bits stuck to the bottom of the pot with a wooden spoon. Those bits are pure flavor.""",
   "onions sauteing pot wooden spoon", "PURE FLAVOR")
sc("""Step three, and this is the one that changes everything. Add the cumin, oregano and chili powder right into the onions and the fat, and stir them for one minute before any liquid goes in. The heat wakes up the spices. You'll smell it the second it happens. Spices dumped into broth just float there, dusty and flat. Toasted in fat, they bloom.""",
   "toasting spices pot onions", "WAKE UP THE SPICES")
sc("""Step four. Pour in the broth and the green chiles, with all their juice. Put the chicken back in. Bring it to a boil, turn it down to a gentle simmer, and cook it with the lid tilted for twenty-five minutes. Then take the chicken out, pull it apart with two forks into bite-sized shreds, and put it back in the pot.""",
   "shredding chicken two forks", "PULL IT APART")
sc("""Step five, my secret, the one Linda said was better than hers. Add the beans. Then take one cup of the beans and broth out, mash it with a fork or a potato masher until it's a thick paste, and stir it back in. That mashed bean thickens the chili like nothing else, and makes it creamy without any flour. Simmer ten more minutes.""",
   "mashing beans fork bowl", "MASH ONE CUP")
sc("""Step six. Turn off the heat. Cut the cream cheese into cubes and stir it in until it melts, then the sour cream. Don't let it boil after the cream goes in, or it can separate. Then squeeze in the lime juice. Taste it. Add salt until it's right. Most people are afraid of salt, and it's the reason their chili tastes like nothing.""",
   "stirring cream cheese chili pot", "DON'T BE AFRAID OF SALT")

sc("""If you're in a hurry on a weeknight, sweetheart, here's the shortcut. Use a store rotisserie chicken, pulled into shreds. Brown the onions in a spoon of butter, toast the spices, add the broth and chiles, simmer fifteen minutes, then the chicken and beans. You lose a little of the brown flavor, but you'll have supper on the table in thirty minutes, and it's still better than any can.""",
   "rotisserie chicken shredded kitchen", "THIRTY MINUTES")

ch("Five mistakes that make it bland")
sc("""So the five mistakes, honey. Mistake one, putting raw chicken straight in the broth, with no browning. Mistake two, dumping the spices into the liquid instead of toasting them in the fat. Mistake three, using water instead of broth. Water makes watery chili. It's right there in the name.""",
   "pale boiled chicken soup pot", "WATER MAKES WATERY CHILI")
sc("""Mistake four, forgetting the acid. A squeeze of lime at the very end is what makes all the other flavors wake up. Without it, white chili tastes heavy and muddy. If you don't have a lime, a spoon of vinegar or the juice from a jar of pickled jalapenos. And mistake five, too little salt. Taste, salt, stir, taste again.""",
   "lime squeeze over bowl", "THE SQUEEZE OF LIME")
sc("""And if it's too thin, don't add flour. Mash more beans, or let it simmer with the lid off for ten minutes. If it's too thick, a splash of broth. And if it isn't spicy enough for your family, a chopped jalapeno with the onions, or a pinch of cayenne. My grandson puts hot sauce on everything, including my apple pie, so I gave up arguing.""",
   "hot sauce bottle chili bowl", "INCLUDING MY APPLE PIE")

ch("Serving it")
sc("""Serve it in deep bowls, with whatever toppings you have. Shredded Monterey Jack cheese, a spoon of sour cream, sliced green onions, avocado, crushed tortilla chips on top for crunch. Put the toppings in little bowls in the middle of the table and let everybody make their own. Children eat twice as much when they get to build it themselves.""",
   "chili toppings bowls cheese avocado", "LET THEM BUILD IT")
sc("""And make a pan of cornbread to go with it. Or do what my father would have done and crumble saltine crackers right on top. White chili freezes beautifully, so I make a double batch and freeze half in quart containers. Then on a cold Tuesday in January, it's dinner in ten minutes. Freeze it before you add the cream cheese and sour cream, and stir them in when you warm it up.""",
   "cornbread skillet chili", "A COLD TUESDAY IN JANUARY")
sc("""It keeps four days in the icebox and tastes even better the next day, when the spices have had time to settle in. And it's the perfect thing to bring to a family with a new baby, or someone who's been sick. A pot of chili, a pan of cornbread, and a bag of chips. They'll eat for three days.""",
   "pot of chili cornbread gift", "THEY'LL EAT FOR THREE DAYS")

sc("""Linda taught me one more thing about this chili, and I'll pass it on. Make it on Saturday afternoon while the football is on, and leave the pot on the back burner on low with a ladle in it. People wander in all afternoon and help themselves. Nobody has to sit down at a certain time. It's the most relaxed meal in my whole cookbook.""",
   "pot on stove ladle afternoon", "LEAVE A LADLE IN IT")

ch("Grandma's kitchen")
sc("""So one more time, honey. Chicken thighs, browned hard. Onions in the chicken fat. Toast the spices before the broth. Green chiles with their juice. Simmer and shred. Mash a cup of beans to make it creamy. Cream cheese off the heat, then a squeeze of lime and plenty of salt. That's my white chicken chili, and nobody has ever called it bland.""",
   "white chicken chili toppings table", "NEVER BLAND")
sc("""Tell me in the comments, sweetheart. Red chili or white chili? And beans or no beans? I know that one starts fights, so be nice to each other. Every day I'm bringing you another recipe from my kitchen. Good night, honey.""",
   "warm kitchen evening chili pot", "RED OR WHITE?")

for s in S:
    s["cuts"], s["moves"] = 4, True

save("grandma27", "The White Chicken Chili EVERYONE Is Making (Why Yours Tastes BLAND)",
     ["Grandma Ruth is a narrated character built from real memories and records of the era.",
      "Recipe as written by Grandma Ruth: 2 lb boneless chicken thighs, 1 onion, 4 garlic cloves, 2 cans (4 oz) green chiles, 3 cans white beans, 4 cups chicken broth, 2 tsp cumin, 1 tsp oregano, 1 tsp chili powder; 4 oz cream cheese, 1/2 cup sour cream, juice of 1 lime.",
      "Blooming ground spices in hot fat releases their fat-soluble aroma compounds."],
     "everyday recipe", minutes=(10, 14.5), voice="en_US-lessac-high")
